// Bounded analysis records are separate from the educational ontology.
let comparisonStatus='ALL', comparisonSubject='ALL';
function comparisonGuide(){
  return `<details class="methodology claim-guide"><summary>Read the claim before reading the connection</summary><p><b>Source-backed:</b> the Receipt preserves New York's wording and source placement. Exact edition and cohort applicability remain unresolved.</p><p><b>Parsed:</b> our representation of what that wording asks students to do. Its derivation is inspectable.</p><p><b>Provisional:</b> a comparison worth investigating. Review can confirm faithful reasoning while the proposed relationship remains tentative.</p><p><b>Rejected:</b> the specific proposal did not hold up. This does not rule out every relationship between the subjects.</p><p>Audit status, claim disposition and curriculum coverage answer different questions. None establishes student mastery.</p></details>`;
}
function comparisonControls(){
  const subjects=[...new Set(comparisons.records.flatMap(r=>r.subjects))];
  return `<div class="comparison-filters"><label for="comparison-status">Show comparisons<select id="comparison-status">${[['ALL','All dispositions'],['PROVISIONAL','Tentative analogies'],['REJECTED','Rejected proposals']].map(([v,l])=>`<option value="${v}" ${comparisonStatus===v?'selected':''}>${l}</option>`).join('')}</select></label><label for="comparison-subject">Subject<select id="comparison-subject">${['ALL',...subjects].map(v=>`<option value="${esc(v)}" ${comparisonSubject===v?'selected':''}>${esc(v==='ALL'?'All subjects':v)}</option>`).join('')}</select></label></div>`;
}
function bindComparisonControls(){
  for(const [id,set] of [['comparison-status',v=>comparisonStatus=v],['comparison-subject',v=>comparisonSubject=v]]){
    const control=document.getElementById(id);if(!control)continue;
    control.onchange=()=>{set(control.value);render();document.getElementById(id).focus();};
  }
}
function comparisonHtml(){
  const all=comparisons.records, records=all.filter(r=>(comparisonStatus==='ALL'||r.status===comparisonStatus)&&(comparisonSubject==='ALL'||r.subjects.includes(comparisonSubject))), provisional=all.filter(r=>r.status==='PROVISIONAL').length;
  return `<div class="section-head"><h2>Three subjects, three comparisons</h2><span>${provisional} candidate analogy · ${all.length-provisional} rejected equivalences · 0 accepted links</span></div><p>Compare what each expectation asks a student to do, not just the words it uses. These analysis records passed a separate AI audit with recorded limits. The analogy remains provisional and the two equivalence proposals remain rejected. They do not change either student's expectations or create graph edges.</p>${comparisonGuide()}${comparisonControls()}<p id="comparison-count" role="status" aria-live="polite">Showing ${records.length} of ${all.length} comparisons.</p>${records.length?'':'<div class="panel comparison-empty"><h3>No comparisons match these filters</h3><p>Try another subject or disposition. This is a filter result, not evidence that no relationship exists.</p></div>'}${records.map(r=>`<details class="comparison-card" id="${esc(r.id)}"><summary><span class="comparison-heading">${esc(r.title)}</span><span class="comparison-verdict">${esc(r.disposition_label)}</span></summary><p class="muted">${esc(r.subjects.join(' / '))} · ${esc(r.id)}</p><h3>Proposal tested</h3><p>${esc(r.proposal)}</p><h3>What the sources support in common</h3><p>${esc(r.commonality)}</p><div class="comparison-sources">${r.evidence.map((e,i)=>`<section><h3>${esc(r.subjects[i])} · ${esc(node(e.standard_id).label)}</h3><blockquote>${esc(e.quotation)}</blockquote>${row(e.standard_id,'Open source Receipt · page '+e.pdf_page)}${row(e.node_id,'Open the parsed expectation')}</section>`).join('')}</div><h3>Where the requirements differ</h3><div class="comparison-axes">${r.axes.map(a=>`<section><h4>${esc(a.axis)}</h4><div><p><b>${esc(r.subjects[0])}</b> ${esc(a.left)}</p><p><b>${esc(r.subjects[1])}</b> ${esc(a.right)}</p></div></section>`).join('')}</div><h3>Disposition</h3>${badge(r.status)}<p>${esc(r.decision)}</p><h3>What is not established</h3><p>${esc(r.not_established)}</p><h3>Source connection check</h3><p>${esc(r.source_context)}</p><details class="comparison-next"><summary>Unresolved question · what would move this forward?</summary><p>${esc(r.next_evidence)}</p><p>Reopen the source Receipts above before proposing a new relationship. This is a research lead, not another student expectation.</p></details><p class="muted">At authoring: ${esc(r.review_status)}. The separate Wednesday audit now covers this frozen record; see the current review notice. Evidence snapshots are tied to the archived source hashes and the specific source/parsed records. A later change requires rechecking the comparison.</p></details>`).join('')}<details class="methodology"><summary>Method and limits</summary><p>${esc(comparisons.scope)} We compared action, object, evidence, required product, placement, and boundary. Similarity is not equivalence; source cross-references are not automatically prerequisites. A rejection applies to the stated proposal, not every possible relationship between the subjects.</p><p>Grades 6–8 science placement stays separate from Grade 7 mathematics and ELA. No mastery, transfer, developmental sequence or shared capability hierarchy is asserted.</p><p><a href="evidence/science-full/page-34.png" target="_blank" rel="noopener">Inspect the science source's own connection box</a> · <a href="${gitPath('docs/wednesday-comparisons.md')}" target="_blank" rel="noopener">Comparison record and review limits</a></p></details>`;
}
